from ledger import Ledger
from threading import RLock
from typing import Tuple, Dict


class IdempotencyConflict(Exception):
    pass


class PaymentService:
    def __init__(self, ledger: Ledger):
        self.ledger = ledger
        # idempotency_key -> response payload (dict) and status_code
        self.idempotency_store: Dict[str, Tuple[int, dict]] = {}
        self.idempotency_lock = RLock()

    def get_payment(self, payment_id: str) -> dict:
        with self.ledger.lock:
            if payment_id not in self.ledger.payments:
                raise KeyError(payment_id)
            return dict(self.ledger.payments[payment_id])

    def _record_refund(self, payment_id: str, amount: int) -> dict:
        payment = self.ledger.payments[payment_id]
        payment["refunded"] += amount
        # update status based on remaining amount
        if payment["refunded"] == payment["amount"]:
            payment["status"] = "refunded"
        else:
            payment["status"] = "partially_refunded"
        return {
            "payment_id": payment_id,
            "amount": amount,
            "refunded_total": payment["refunded"],
            "status": payment["status"],
        }

    def process_refund(
        self, payment_id: str, amount: int, idempotency_key: str
    ) -> Tuple[int, dict]:
        # Idempotency handling – ensure atomic check‑and‑set
        with self.idempotency_lock:
            if idempotency_key in self.idempotency_store:
                stored_status, stored_payload = self.idempotency_store[idempotency_key]
                # Verify that stored key matches same payment and amount
                if (
                    stored_payload.get("payment_id") == payment_id
                    and stored_payload.get("amount") == amount
                ):
                    return stored_status, stored_payload
                else:
                    raise IdempotencyConflict(
                        "Idempotency key conflict with different payment or amount"
                    )
        # Not a replay – perform business validation and mutation under ledger lock
        with self.ledger.lock:
            if payment_id not in self.ledger.payments:
                raise KeyError(payment_id)
            payment = self.ledger.payments[payment_id]
            if payment["status"] == "cancelled":
                raise ValueError("Cannot refund a cancelled payment")
            remaining = payment["amount"] - payment["refunded"]
            if amount > remaining:
                raise ValueError("Refund amount exceeds remaining captured amount")
            # Apply refund
            response_payload = self._record_refund(payment_id, amount)
            status_code = 201
        # Store idempotency result after successful mutation
        with self.idempotency_lock:
            self.idempotency_store[idempotency_key] = (status_code, response_payload)
        return status_code, response_payload

